export const DECISIONS = [
  { axis: 'Executor', decision: 'Nostr, instance and Coinos work runs on a dedicated tokio thread; the window awaits only two futures channels. gpui\'s executor is not tokio and a tokio future polled there aborts the process. The Chat pane is the one exception: it polls its SSE body on gpui\'s executor, which is why only ReqwestClient::user_agent may be used.', adr: 'src/nostr.rs:3-6, src/main.rs:73-80, src/chat.rs:150-152' },
  { axis: 'TLS', decision: 'rustls\'s ring provider is installed before any client exists, because gpui-kit and reqwest pull ring and aws-lc-rs both and rustls refuses to guess.', adr: 'src/nostr.rs:264-269' },
  { axis: 'UI stack', decision: 'One crates.io dependency, gpui-kit 0.6.0, plus the reqwest client it does not re-export. Cargo refusing two gpui-pre versions is the safety net.', adr: 'Cargo.toml:8-13' },
  { axis: 'Publish door', decision: 'DLists and claims leave through POST /api/strfry/publish, never a relay socket; an event sent to public relays never reaches the bounty machinery. The kind-0 profile update goes through the door first and then to three public relays.', adr: 'src/api.rs:523-526, src/nostr.rs:665-684' },
  { axis: 'Receipt truth', decision: 'A kind-9735 pushed by the relay only triggers an early poll. A receipt is a fact only when the server returns it in claims[].zapReceipt, because only the server knows the delegate key.', adr: 'src/nostr.rs:1062-1068' },
  { axis: 'Profile write', decision: 'The kind-0 is merged field by field and only lud16 changes. A profile rebuilt from nothing would wipe the name and picture on every relay that accepts it.', adr: 'src/nostr.rs:613-622' },
  { axis: 'Key precedence', decision: 'MC_ISSUER_NSEC / MC_CLAIMANT_NSEC win over the keychain. Forget this key deletes the keychain entry only, so an env key comes straight back.', adr: 'src/secrets.rs:55-56, 216-218' },
  { axis: 'Coinos order', decision: 'The Coinos login is written to the keychain before POST /api/register and deleted only on an explicit refusal, so a signup that times out on the way back is never lost.', adr: 'src/secrets.rs:223-226' },
  { axis: 'Watching', decision: 'One live bounty watcher at a time. Ledgers outlive watchers, so re-selecting a bounty never replays its history into the feed.', adr: 'src/nostr.rs:345-350, 456-458' },
  { axis: 'Validate first', decision: 'The bounty form is checked before anything publishes, because the DList goes out first and cannot be unpublished.', adr: 'src/shell.rs:1268-1273' },
  { axis: 'Secrets', decision: 'nsecs, the Coinos password and the Anthropic key cross threads only inside Secret, whose Debug prints <redacted>. Error text is fixed, never the input.', adr: 'src/secrets.rs:4-7' },
  { axis: 'Chat backend', decision: 'The desktop chat calls api.anthropic.com directly. The worker exists for clients that should not hold a key and is not called from src/.', adr: 'src/chat.rs:29, worker/README.md:4-6' },
  { axis: 'Chat cell', decision: 'One turn per conversation cell, 409 for a second POST. A finally block releases the cell on every ending the runtime can see; a 30 s stale clock covers the one it cannot, a client hangup. No auth: the tailnet is the perimeter.', adr: 'worker/src/index.ts:12-14, 55-56, 130-134, 318-325' },
  { axis: 'Packaging', decision: 'Ship an unsigned .app with a READ ME FIRST for Gatekeeper rather than sign and notarize.', adr: 'scripts/make-app.sh:8-17' },
];

